using System.Diagnostics;
static class Measurements
{
    static long sink;
    static Student[] Queries(Student[] a,int count){var r=new Random(214);var q=new Student[count];for(int i=0;i<count;i++)q[i]=a[r.Next(a.Length)];return q;}
    static double Time(Student[] a,Student[] q,int count,bool sorted){var copy=(Student[])a.Clone();var sw=Stopwatch.StartNew();if(sorted)Array.Sort(copy,Program.Compare);long sum=0;for(int i=0;i<count;i++)sum+=sorted?Search.BinarySearch(copy,q[i],Program.Compare,out _):Search.LinearSearch(copy,q[i],Program.Compare,out _);sw.Stop();sink=sum;return sw.Elapsed.TotalMilliseconds;}
    public static void Run(){Console.WriteLine("\nЗавдання 5: порівняння на відсортованих масивах");Console.WriteLine("| n | Лінійний | Бінарний | Відношення | Теорія |");foreach(int n in new[]{1000,10000,100000,1000000}){var a=Program.Data(n);Array.Sort(a,Program.Compare);var q=Queries(a,100);long l=0,b=0;foreach(var t in q){Search.LinearSearch(a,t,Program.Compare,out int lc);Search.BinarySearch(a,t,Program.Compare,out int bc);l+=lc;b+=bc;}Console.WriteLine($"| {n} | {l/100.0:F2} | {b/100.0:F2} | {(double)l/b:F2} | {n/2} / {Math.Ceiling(Math.Log2(n))} |");}var raw=Program.Data(100000);var queries=Queries(raw,100);Time(raw,queries,100,false);Time(raw,queries,100,true);Console.WriteLine("\n| q | Лінійно, мс | Сортування + бінарно, мс | Хто швидший |");int first=0;foreach(int q in new[]{1,5,10,20,30,50,100}){double l=double.MaxValue,b=double.MaxValue;for(int i=0;i<3;i++){l=Math.Min(l,Time(raw,queries,q,false));b=Math.Min(b,Time(raw,queries,q,true));}if(b<l&&first==0)first=q;Console.WriteLine($"| {q} | {l:F4} | {b:F4} | {(b<l?"Бінарний":"Лінійний")} |");}Console.WriteLine(first==0?"Точка окупності не знайдена до q=100":$"Перша виміряна точка окупності: q={first}");}
}
